from packaging.version import Version
import netCDF4

def sanitize_version(v):
    if isinstance(v, str) and '-development' in v:
        return v.replace('-development', '.dev0')
    return v

try:
    v_str = '4.9.3-development'
    print(f"Original: {v_str}")
    print(f"Sanitized: {sanitize_version(v_str)}")
    print(f"Version object: {Version(sanitize_version(v_str))}")
except Exception as e:
    print(f"Error: {e}")

